<template>

  <div class="container">
    <div class="App">
      <span style="font-size: 20px; ">AI MODEL</span>


<!--      <div class="Input" >-->
<!--        <h3>Prompt</h3>-->
<!--        <textarea dir="auto" v-model="request.prompt" placeholder=""/>-->
<!--      </div>-->

      <div class="Input" >
        <h3>Prompt</h3>
        <textarea dir="auto" v-model="request.text" placeholder=""/>
      </div>

      <el-button  :loading="isSubmitLoading" class="Button" @click="handleSubmit">Submit</el-button>

      <h1 style="font-size: 18px; color: #333; white-space: pre-line">{{ result }}</h1>



      <div style="height: 200px; margin-top: 60px;">
        <h4 style="text-align: center; color: #999">@Power by AppLocalize.top</h4>
      </div>

    </div>
  </div>

</template>

<script>
import {aiModel, dating, getLanguages, getStrings, submitStrings} from "../api/user"
export default {
  data() {
    return {
      request: {
        text: "",
      },
      result: 'Result',

      isSubmitLoading: false,
    }
  },

  methods: {

    handleSubmit() {
      this.isSubmitLoading = true
      aiModel(this.request).then((data) => {
        this.isSubmitLoading = false
        console.log(data)
        this.result = data.data.text
        if (data.data.errCode == 0) {
          this.result = data.data.text
        } else {
          this.result = data.data.errMsg
        }
      })

      this.isSubmitLoading = true
      const request = {
        "projectKey": this.$route.params.id,
        "srcLanguage": "en",
        "toLanguage": this.$route.query.tl,
        "data": []
      }

      this.strings.forEach((item) => {
        if (item.value !== undefined && item.value !== "" && item.value !== item[this.targetField]) {
          const d = {"transId": item.transId, "english": item.en, "source": item[this.targetField],  "value": item.value}
          request.data.push(d)
        }
      })
      submitStrings(request).then((data) => {
        this.isSubmitLoading = false
        if (data.code == 200) {
          this.desc = "Submitted successfully, thank you for your contribution.";
          this.showResult = true;
        }
      })

    },
  },
}
</script>

